(function() {
  'use strict';

  // --- Data Source ---
  // Extracted from window.paperMindData.tables (p33-figure-6)
  // Values are approximations from the visual chart in the paper
  const chartData = {
    skill: [
      { label: 'Q1 (最低技能)', value: 0.35, error: 0.05 },
      { label: 'Q2', value: 0.20, error: 0.04 },
      { label: 'Q3', value: 0.18, error: 0.04 },
      { label: 'Q4', value: 0.16, error: 0.04 },
      { label: 'Q5 (最高技能)', value: 0.02, error: 0.03 }
    ],
    tenure: [
      { label: '0 月', value: 0.35, error: 0.06 },
      { label: '1-2 月', value: 0.18, error: 0.04 },
      { label: '3-6 月', value: 0.16, error: 0.04 },
      { label: '7-12 月', value: 0.14, error: 0.04 },
      { label: '>12 月', value: -0.02, error: 0.03 }
    ]
  };

  // --- State Management ---
  let currentStep = 0;
  let currentView = 'skill'; // 'skill' or 'tenure'
  const totalSteps = 3;

  // --- DOM Elements ---
  const stepPanels = document.querySelectorAll('.step-panel');
  const indicators = document.querySelectorAll('.indicator');
  const prevBtn = document.getElementById('step-prev');
  const nextBtn = document.getElementById('step-next');
  const canvas = document.getElementById('chart-canvas');
  const legendContainer = document.getElementById('chart-legend');
  const toggleButtons = document.querySelectorAll('.btn-toggle');

  // --- Stepper Logic ---
  function updateStepper() {
    // Update Panels
    stepPanels.forEach((panel, index) => {
      panel.classList.toggle('active', index === currentStep);
    });

    // Update Indicators
    indicators.forEach((ind, index) => {
      ind.classList.toggle('active', index === currentStep);
    });

    // Update Buttons
    prevBtn.disabled = currentStep === 0;
    nextBtn.disabled = currentStep === totalSteps - 1;
    nextBtn.textContent = currentStep === totalSteps - 1 ? '完成' : '下一步';
  }

  prevBtn.addEventListener('click', () => {
    if (currentStep > 0) {
      currentStep--;
      updateStepper();
    }
  });

  nextBtn.addEventListener('click', () => {
    if (currentStep < totalSteps - 1) {
      currentStep++;
      updateStepper();
    }
  });

  // --- Chart Rendering Logic (Native Canvas) ---
  function drawChart(dataSet) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const padding = { top: 40, right: 30, bottom: 60, left: 50 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // Clear Canvas
    ctx.clearRect(0, 0, width, height);

    // Calculate Scales
    const maxValue = Math.max(...dataSet.map(d => d.value + d.error), 0.4);
    const minValue = Math.min(...dataSet.map(d => d.value - d.error), -0.1);
    const yRange = maxValue - minValue;
    const barWidth = (chartWidth / dataSet.length) * 0.6;
    const gap = (chartWidth / dataSet.length) * 0.4;

    // Helper: Map Value to Y Coordinate
    const getY = (val) => {
      return height - padding.bottom - ((val - minValue) / yRange) * chartHeight;
    };

    const zeroY = getY(0);

    // Draw Axes
    ctx.beginPath();
    ctx.strokeStyle = '#718096';
    ctx.lineWidth = 1;
    // Y Axis
    ctx.moveTo(padding.left, padding.top);
    ctx.lineTo(padding.left, height - padding.bottom);
    // X Axis (Zero Line)
    ctx.moveTo(padding.left, zeroY);
    ctx.lineTo(width - padding.right, zeroY);
    ctx.stroke();

    // Draw Bars and Error Bars
    dataSet.forEach((item, index) => {
      const x = padding.left + (index * (barWidth + gap)) + (gap / 2);
      const yValue = getY(item.value);
      const yTop = getY(item.value + item.error);
      const yBottom = getY(item.value - item.error);
      const barHeight = zeroY - yValue;

      // Draw Bar
      ctx.fillStyle = item.value >= 0 ? '#2C5282' : '#E53E3E';
      ctx.fillRect(x, item.value >= 0 ? yValue : zeroY, barWidth, Math.abs(barHeight));

      // Draw Error Bar
      ctx.beginPath();
      ctx.strokeStyle = '#2D3748';
      ctx.lineWidth = 2;
      // Vertical line
      ctx.moveTo(x + barWidth / 2, yTop);
      ctx.lineTo(x + barWidth / 2, yBottom);
      // Top cap
      ctx.moveTo(x + barWidth / 2 - 5, yTop);
      ctx.lineTo(x + barWidth / 2 + 5, yTop);
      // Bottom cap
      ctx.moveTo(x + barWidth / 2 - 5, yBottom);
      ctx.lineTo(x + barWidth / 2 + 5, yBottom);
      ctx.stroke();

      // Draw Label
      ctx.fillStyle = '#4A5568';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, x + barWidth / 2, height - padding.bottom + 20);

      // Draw Value Label
      ctx.fillStyle = '#2D3748';
      ctx.font = 'bold 12px sans-serif';
      const labelY = item.value >= 0 ? yValue - 10 : yBottom + 20;
      ctx.fillText((item.value * 100).toFixed(0) + '%', x + barWidth / 2, labelY);
    });

    // Draw Y Axis Labels
    ctx.fillStyle = '#718096';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';
    const ySteps = 5;
    for (let i = 0; i <= ySteps; i++) {
      const val = minValue + (yRange * i) / ySteps;
      const y = getY(val);
      ctx.fillText(val.toFixed(2), padding.left - 10, y + 4);
      // Grid line
      ctx.beginPath();
      ctx.strokeStyle = '#E2E8F0';
      ctx.lineWidth = 0.5;
      ctx.setLineDash([4, 4]);
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  function updateChart() {
    const data = currentView === 'skill' ? chartData.skill : chartData.tenure;
    drawChart(data);

    // Update Legend Text (Optional, could be more dynamic)
    legendContainer.innerHTML = `<span style="color:var(--accent)">■</span> 生产力提升百分比 (Log 变换)`;
  }

  // --- Event Listeners for Chart Toggles ---
  toggleButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      toggleButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentView = btn.dataset.view;
      updateChart();
    });
  });

  // --- Initialization ---
  function init() {
    updateStepper();
    updateChart();

    // Handle reduced motion preference
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      document.querySelectorAll('.step-panel').forEach(el => {
        el.style.animation = 'none';
      });
    }
  }

  init();
})();
